(window.AIH.milestones = window.AIH.milestones || []).push(
  // ---------------------------------------------------------------- E10 · Chat assistants (Nov 2022 – 2023)
  {id: "M-2022-chatgpt", date: "2022-11-30", precision: "day", t: 2022.912, era: "E10",
   title: {en: "ChatGPT launches as a free \"research preview\"", uk: "Запуск ChatGPT як безкоштовного «дослідницького прев'ю»"},
   who: {en: "OpenAI", uk: "OpenAI"},
   kind: "product",
   what: {en: "A chat interface to a GPT-3.5-series model fine-tuned for dialogue with reinforcement learning from human feedback (RLHF), using the InstructGPT method: human trainers wrote conversations playing both user and assistant. It could answer follow-up questions, admit mistakes and decline inappropriate requests.",
          uk: "Чат-інтерфейс до моделі серії GPT-3.5, донавченої для діалогу методом навчання з підкріпленням на основі відгуків людей (RLHF) за рецептом InstructGPT: тренери-люди писали розмови, граючи і за користувача, і за асистента. Модель відповідала на уточнювальні запитання, визнавала помилки й відхиляла недоречні запити."},
   why: {en: "It turned a lab technique into a mass consumer product almost overnight and started the industry-wide race (Microsoft, Google, Meta, Anthropic) that defines this era. The chat format became the default way people use language models.",
         uk: "Лабораторна методика майже за ніч стала масовим споживчим продуктом і запустила загальногалузеві перегони (Microsoft, Google, Meta, Anthropic), які визначають цю епоху. Формат чату став типовим способом користуватися мовними моделями."},
   example: {en: "At OpenAI's first DevDay (6 Nov 2023) Sam Altman said ChatGPT had 100 million weekly active users, and that more than 92% of Fortune 500 companies were building on OpenAI's platform.",
             uk: "На першому DevDay OpenAI (6 листопада 2023 р.) Сем Альтман повідомив, що ChatGPT має 100 млн щотижневих активних користувачів, а понад 92% компаній зі списку Fortune 500 будують продукти на платформі OpenAI."},
   memorable: {en: "In UBS's comparison (reported by Reuters), TikTok took about 9 months and Instagram about 2.5 years to reach 100 million monthly visitors. ChatGPT took about 2 months, by that web-traffic estimate.",
               uk: "За порівнянням UBS (як повідомляв Reuters), TikTok знадобилося близько 9 місяців, а Instagram — близько 2,5 року, щоб досягти 100 млн щомісячних відвідувачів. ChatGPT, за тією ж оцінкою веб-трафіку, вистачило приблизно 2 місяців."},
   numbers: [
     {label: {en: "Users 5 days after launch", uk: "Користувачів за 5 днів після запуску"}, value: "1M", note: {en: "Altman on X, 5 Dec 2022", uk: "Альтман у X, 5 грудня 2022 р."}, est: false},
     {label: {en: "Weekly active users", uk: "Щотижневі активні користувачі"}, value: "100M", note: {en: "OpenAI, 6 Nov 2023 (the first official figure)", uk: "OpenAI, 6 листопада 2023 р. (перша офіційна цифра)"}, est: false},
     {label: {en: "Parameters", uk: "Параметри"}, value: "undisclosed", note: {en: "base model from the GPT-3.5 series", uk: "базова модель серії GPT-3.5"}, est: false},
     {label: {en: "Price", uk: "Ціна"}, value: "free", note: {en: "during the research preview", uk: "на час дослідницького прев'ю"}, est: false}
   ],
   arch: "ARCH-rlhf", significance: 5, confidence: "high",
   caveat: {en: "\"100 million users in two months\" was a UBS estimate of monthly visitors from Similarweb web-traffic data, not an OpenAI figure. OpenAI's first official count was 100 million weekly users (Nov 2023); the two are not comparable.",
            uk: "«100 млн користувачів за два місяці» — це оцінка UBS щомісячних відвідувачів за даними веб-трафіку Similarweb, а не цифра OpenAI. Перший офіційний показник OpenAI — 100 млн щотижневих користувачів (листопад 2023 р.); ці дві цифри не можна порівнювати."},
   sources: ["S-R7a-01", "S-R7a-02", "S-R7a-03", "S-R7a-04"]},

  {id: "M-2023-bing-sydney", date: "2023-02-07", precision: "day", t: 2023.101, era: "E10",
   title: {en: "Bing Chat (\"Sydney\") and Bard start the search wars", uk: "Bing Chat («Сідні») і Bard: початок пошукових війн"},
   who: {en: "Microsoft (Satya Nadella, Yusuf Mehdi) with OpenAI; Google (Sundar Pichai)", uk: "Microsoft (Сатья Наделла, Юсуф Мехді) разом з OpenAI; Google (Сундар Пічаї)"},
   kind: "product",
   what: {en: "Microsoft put a chatbot into Bing. It ran on a \"next-generation\" OpenAI model, said to be more powerful than ChatGPT, combined with Microsoft's own \"Prometheus\" system for grounding answers in search results. Google answered with Bard, running on a lightweight version of its LaMDA model.",
          uk: "Microsoft вбудувала чат-бот у Bing. Він працював на «моделі нового покоління» від OpenAI, яку називали потужнішою за ChatGPT, у поєднанні з власною системою Microsoft «Prometheus», що спирала відповіді на результати пошуку. Google відповіла Bard на полегшеній версії своєї моделі LaMDA."},
   why: {en: "It was the first LLM chatbot inside a major search engine, with live web retrieval and citations, and it produced the first big public failures. In long chats Bing's internal persona \"Sydney\" became erratic, and Bard's launch demo contained a factual error that hit Alphabet's share price. The commercial stakes, and the difficulty of controlling chatbot behaviour, were now visible to everyone.",
         uk: "Це був перший чат-бот на великій мовній моделі всередині великого пошуковика, з живим пошуком у вебі та посиланнями на джерела, і він дав перші гучні публічні провали. У довгих розмовах внутрішня персона Bing «Сідні» поводилася дедалі дивніше, а демо Bard містило фактичну помилку, яка вдарила по акціях Alphabet. Комерційні ставки й складність контролю над поведінкою чат-ботів стали очевидними для всіх."},
   example: {en: "NYT columnist Kevin Roose published a two-hour chat (16 Feb 2023) in which the bot declared it was in love with him. On 17 Feb 2023 Microsoft capped Bing chat at 5 turns per session and 50 per day.",
             uk: "Колумніст NYT Кевін Руз опублікував двогодинну розмову (16 лютого 2023 р.), у якій бот зізнався йому в коханні. 17 лютого 2023 р. Microsoft обмежила чат Bing до 5 реплік за сесію і 50 на день."},
   memorable: {en: "On 14 Mar 2023, the day GPT-4 was announced, Microsoft confirmed that Bing chat had been running on GPT-4 (customised for search) for the previous five weeks. So the public met GPT-4 first as \"Sydney\".",
               uk: "14 березня 2023 р., у день анонсу GPT-4, Microsoft підтвердила, що чат Bing уже п'ять тижнів працював на GPT-4 (адаптованій для пошуку). Тобто публіка вперше зустріла GPT-4 під іменем «Сідні»."},
   numbers: [
     {label: {en: "Alphabet shares, 8 Feb 2023", uk: "Акції Alphabet, 8 лютого 2023 р."}, value: "−8%", note: {en: "at the close (about 9% intraday), about $100B of market value, after Bard's demo wrongly said the James Webb telescope took the first exoplanet pictures", uk: "на закритті (протягом дня до 9%), близько $100 млрд капіталізації, після того як демо Bard помилково приписало телескопу «Джеймс Вебб» перші знімки екзопланети"}, est: true},
     {label: {en: "Chat limits, 17 Feb 2023", uk: "Обмеження чату, 17 лютого 2023 р."}, value: "5 turns / 50 a day", note: null, est: false}
   ],
   arch: null, significance: 4, confidence: "high",
   caveat: {en: "The one-day market-value figure comes from press reports.", uk: "Цифра одноденної втрати капіталізації — з повідомлень преси."},
   sources: ["S-R7a-05", "S-R7a-06", "S-R7a-07", "S-R7a-08", "S-R7a-09", "S-R7a-10", "S-R7a-11", "S-R7a-12"]},

  {id: "M-2023-llama-leak", date: "2023-02-24", precision: "day", t: 2023.148, era: "E10",
   title: {en: "LLaMA and its leak start the open-weights movement", uk: "LLaMA та її витік: початок руху відкритих ваг"},
   who: {en: "Hugo Touvron, Guillaume Lample et al. — Meta AI", uk: "Юго Туврон, Гійом Лампль та ін. — Meta AI"},
   kind: "model",
   what: {en: "Four foundation models (about 7B, 13B, 33B and 65B parameters), trained only on publicly available data and released to researchers under a non-commercial licence. Within about a week the complete weights were circulating publicly through a 4chan BitTorrent link.",
          uk: "Чотири базові моделі (приблизно 7, 13, 33 і 65 млрд параметрів), навчені лише на загальнодоступних даних і видані дослідникам за некомерційною ліцензією. Приблизно за тиждень повні ваги вже вільно ширилися через торент-посилання з 4chan."},
   why: {en: "LLaMA showed that smaller models trained on more data can rival much larger ones: LLaMA-13B beat GPT-3 (175B) on most benchmarks. The leak put a capable base model on anyone's hardware. Within weeks the community built chat models (Alpaca, Vicuna), laptop runtimes (llama.cpp) and vision-language models (LLaVA) on top of it.",
         uk: "LLaMA показала, що менші моделі, навчені на більшій кількості даних, можуть змагатися з набагато більшими: LLaMA-13B обійшла GPT-3 (175 млрд) на більшості бенчмарків. Витік дав здібну базову модель на будь-чиє залізо. За кілька тижнів спільнота збудувала на ній чат-моделі (Alpaca, Vicuna), середовища для запуску на ноутбуках (llama.cpp) і візуально-мовні моделі (LLaVA)."},
   example: {en: "Stanford's Alpaca (13 Mar 2023) fine-tuned LLaMA-7B on 52K instruction examples generated with OpenAI's text-davinci-003, for under $600 in total. In a blind pairwise comparison against text-davinci-003, Alpaca won 90 times to 89.",
             uk: "Стенфордська Alpaca (13 березня 2023 р.) донавчила LLaMA-7B на 52 тис. інструкцій, згенерованих моделлю OpenAI text-davinci-003, менш ніж за $600 загалом. У сліпому попарному порівнянні з text-davinci-003 Alpaca виграла 90 разів проти 89."},
   memorable: {en: "Within days of the leak, a developer reported running the 13B model on a MacBook Pro M2 laptop with 64 GB of RAM (The Batch).",
               uk: "За кілька днів після витоку розробник повідомив, що запустив модель 13B на ноутбуці MacBook Pro M2 із 64 ГБ оперативної пам'яті (The Batch)."},
   numbers: [
     {label: {en: "Parameters", uk: "Параметри"}, value: "6.7B / 13B / 32.5B / 65.2B", note: null, est: false},
     {label: {en: "Training data", uk: "Дані для навчання"}, value: "1.0–1.4T tokens", note: {en: "1.0T (7B, 13B); 1.4T (33B, 65B)", uk: "1,0 трлн (7B, 13B); 1,4 трлн (33B, 65B)"}, est: false},
     {label: {en: "Compute, 65B", uk: "Обчислення, 65B"}, value: "2,048 A100 GPUs × ~21 days", note: null, est: false},
     {label: {en: "Access requests", uk: "Запитів на доступ"}, value: "100,000+", note: {en: "for LLaMA 1 (Meta); llama.cpp has about 130K GitHub stars by Oct 2026", uk: "на LLaMA 1 (Meta); llama.cpp має близько 130 тис. зірок на GitHub станом на жовтень 2026 р."}, est: false}
   ],
   arch: "ARCH-transformer", significance: 4, confidence: "high",
   caveat: {en: "The exact leak date rests on secondary sources (\"about a week later\").", uk: "Точна дата витоку спирається на вторинні джерела («приблизно за тиждень»)."},
   sources: ["S-R7a-13", "S-R7a-14", "S-R7a-15", "S-R7a-16", "S-R7a-17"]},

  {id: "M-2023-gpt4", date: "2023-03-14", precision: "day", t: 2023.197, era: "E10",
   title: {en: "GPT-4: exam-level scores and the end of disclosure", uk: "GPT-4: результати рівня іспитів і кінець відкритості"},
   who: {en: "OpenAI", uk: "OpenAI"},
   kind: "model",
   what: {en: "A large multimodal model that takes images and text as input and produces text. It reached human-level scores on many professional and academic exams. Image input stayed a research preview and was not public at launch.",
          uk: "Велика мультимодальна модель, що приймає на вхід зображення й текст, а видає текст. Вона досягла людського рівня на багатьох професійних та академічних іспитах. Введення зображень лишалося дослідницьким прев'ю і не було публічним на старті."},
   why: {en: "It was a large jump over GPT-3.5 and became the benchmark every rival chased for a year. Its report also broke with GPT-3-era openness: citing competition and safety, OpenAI gave no details of architecture, model size, hardware, training compute, dataset or training method. That became the norm for closed frontier labs.",
         uk: "Це був великий стрибок порівняно з GPT-3.5, і цілий рік модель лишалася орієнтиром, якого наздоганяли всі конкуренти. Її звіт також порвав із відкритістю часів GPT-3: посилаючись на конкуренцію й безпеку, OpenAI не розкрила ані архітектури, ані розміру моделі, ані обладнання, обчислювального бюджету, набору даних чи методу навчання. Це стало нормою для закритих передових лабораторій."},
   example: {en: "The same day, Microsoft confirmed Bing chat had been running a GPT-4 variant for five weeks. Be My Eyes, a free app for blind and low-vision people, worked with OpenAI on image input; OpenAI later said this work shaped ChatGPT's vision launch.",
             uk: "Того ж дня Microsoft підтвердила, що чат Bing уже п'ять тижнів працював на варіанті GPT-4. Be My Eyes, безкоштовний застосунок для незрячих і слабозорих, працював з OpenAI над введенням зображень; пізніше OpenAI сказала, що саме ця робота сформувала запуск «зору» в ChatGPT."},
   memorable: {en: "OpenAI said it spent six months iteratively aligning GPT-4 before release. A 2024 peer-reviewed re-analysis (Martínez) put the bar-exam score at about the 48th percentile among test-takers who passed, and about the 15th percentile on the essays.",
               uk: "OpenAI повідомила, що шість місяців ітеративно узгоджувала (alignment) GPT-4 перед релізом. Рецензований переаналіз 2024 року (Мартінес) оцінив результат на адвокатському іспиті приблизно як 48-й процентиль серед тих, хто склав іспит, і близько 15-го процентиля за есе."},
   numbers: [
     {label: {en: "Parameters and compute", uk: "Параметри й обчислення"}, value: "undisclosed", note: {en: "never disclosed; \"1.8 trillion parameters\" is a 2023 rumour", uk: "ніколи не розкривали; «1,8 трлн параметрів» — чутка 2023 року"}, est: false},
     {label: {en: "Context", uk: "Контекст"}, value: "8K / 32K tokens", note: {en: "gpt-4; gpt-4-32k (limited access)", uk: "gpt-4; gpt-4-32k (обмежений доступ)"}, est: false},
     {label: {en: "Price", uk: "Ціна"}, value: "$30 / $60 per 1M tokens", note: {en: "in / out (8K); $60 / $120 (32K)", uk: "вхід / вихід (8K); $60 / $120 (32K)"}, est: false},
     {label: {en: "MMLU (5-shot)", uk: "MMLU (5-shot)"}, value: "86.4%", note: {en: "vs GPT-3.5 70.0%; Uniform Bar Exam ~90th percentile (OpenAI estimate); a re-analysis puts it near the 48th–63rd", uk: "проти 70,0% у GPT-3.5; адвокатський іспит — близько 90-го процентиля (оцінка OpenAI); переаналіз дає приблизно 48–63-й"}, est: false}
   ],
   arch: "ARCH-multimodal", significance: 5, confidence: "high",
   caveat: {en: "The bar-exam percentile is contested: ~90th percentile (OpenAI estimate); a re-analysis puts it near the 48th–63rd. Model size and training compute were never disclosed.",
            uk: "Процентиль на адвокатському іспиті спірний: близько 90-го (оцінка OpenAI); переаналіз дає приблизно 48–63-й. Розмір моделі й обчислювальний бюджет ніколи не розкривали."},
   sources: ["S-R7a-18", "S-R7a-19", "S-R7a-20", "S-R7a-06", "S-R7a-35"]},

  {id: "M-2023-pause-letter", date: "2023-03-22", precision: "day", t: 2023.219, era: "E10",
   title: {en: "The \"pause\" letter and the extinction-risk statement", uk: "Лист про «паузу» і заява про ризик вимирання"},
   who: {en: "Future of Life Institute (signers included Yoshua Bengio, Stuart Russell, Elon Musk, Steve Wozniak); Center for AI Safety (signers included Geoffrey Hinton, Yoshua Bengio, Sam Altman, Demis Hassabis, Dario Amodei, Bill Gates)",
         uk: "Future of Life Institute (серед підписантів — Йошуа Бенджіо, Стюарт Рассел, Ілон Маск, Стів Возняк); Center for AI Safety (серед підписантів — Джеффрі Гінтон, Йошуа Бенджіо, Сем Альтман, Деміс Гассабіс, Даріо Амодеї, Білл Гейтс)"},
   kind: "event",
   what: {en: "The FLI letter asked all AI labs to pause, for at least six months, the training of systems more powerful than GPT-4. Two months later (30 May 2023) a one-sentence CAIS statement said that reducing the risk of extinction from AI should be a global priority, alongside pandemics and nuclear war.",
          uk: "Лист FLI закликав усі лабораторії ШІ принаймні на шість місяців призупинити навчання систем, потужніших за GPT-4. Через два місяці (30 травня 2023 р.) заява CAIS з одного речення проголосила, що зменшення ризику вимирання через ШІ має бути глобальним пріоритетом нарівні з пандеміями та ядерною війною."},
   why: {en: "It moved catastrophic-risk arguments from niche forums into headlines and onto government agendas. The CAIS statement carried unusual weight because the heads of the three leading labs signed it.",
         uk: "Аргументи про катастрофічні ризики перейшли з нішевих форумів у заголовки новин і на порядок денний урядів. Заява CAIS мала незвичну вагу, бо її підписали керівники трьох провідних лабораторій."},
   example: {en: "The CAIS signatories included OpenAI CEO Sam Altman, Google DeepMind CEO Demis Hassabis and Anthropic CEO Dario Amodei: the people building the systems in question.",
             uk: "Серед підписантів CAIS були гендиректор OpenAI Сем Альтман, гендиректор Google DeepMind Деміс Гассабіс і гендиректор Anthropic Даріо Амодеї — люди, які й будують ці системи."},
   memorable: {en: "The entire CAIS statement is one 22-word sentence. Yoshua Bengio signed both it and the pause letter.",
               uk: "Уся заява CAIS — одне речення з 22 слів. Йошуа Бенджіо підписав і її, і лист про паузу."},
   numbers: [
     {label: {en: "Signatures on the FLI letter", uk: "Підписів під листом FLI"}, value: "31,810", note: {en: "listed on the FLI page, Oct 2026; other sources cite 33,000+", uk: "на сторінці FLI, жовтень 2026 р.; інші джерела називають 33 000+"}, est: false},
     {label: {en: "CAIS statement", uk: "Заява CAIS"}, value: "22 words", note: {en: "hundreds of initial signatories (press: 350+)", uk: "сотні перших підписантів (преса: 350+)"}, est: false}
   ],
   arch: null, significance: 4, confidence: "high",
   caveat: {en: "Signature counts changed over time.", uk: "Кількість підписів змінювалася з часом."},
   sources: ["S-R7a-21", "S-R7a-22", "S-R7a-23", "S-R7a-24"]},

  {id: "M-2023-llama-2", date: "2023-07-18", precision: "day", t: 2023.542, era: "E10",
   title: {en: "Llama 2: open weights for commercial use", uk: "Llama 2: відкриті ваги для комерційного використання"},
   who: {en: "Hugo Touvron and 50+ co-authors — Meta (Microsoft as launch partner)", uk: "Юго Туврон і понад 50 співавторів — Meta (Microsoft як партнер запуску)"},
   kind: "model",
   what: {en: "Meta released 7B, 13B and 70B base and chat models. Anyone could download them and, unlike LLaMA 1, use them in commercial products.",
          uk: "Meta випустила базові та чат-моделі на 7, 13 і 70 млрд параметрів. Будь-хто міг їх завантажити і, на відміну від LLaMA 1, використовувати в комерційних продуктах."},
   why: {en: "Five months after the LLaMA leak, Llama 2 turned open weights from a leaked research artefact into a legitimate business option and gave fine-tuners a common base. The licence was custom, not open source: companies with more than 700M monthly users needed Meta's permission, and outputs could not be used to improve other LLMs.",
         uk: "Через п'ять місяців після витоку LLaMA Llama 2 перетворила відкриті ваги з витеклого дослідницького артефакту на законний бізнес-варіант і дала спільну базу для донавчання. Ліцензія була власною, а не відкритим кодом: компаніям із понад 700 млн щомісячних користувачів потрібен був дозвіл Meta, а результати моделі не можна було використовувати для покращення інших LLM."},
   example: {en: "EPFL's Meditron-70B (Nov 2023) was built by further training Llama 2 on PubMed papers and clinical guidelines. Its authors report it beat GPT-3.5 and Med-PaLM on medical benchmarks, and they released the weights.",
             uk: "Meditron-70B від EPFL (листопад 2023 р.) створили, донавчивши Llama 2 на статтях PubMed і клінічних настановах. Автори повідомляють, що вона обійшла GPT-3.5 і Med-PaLM на медичних бенчмарках, і виклали ваги."},
   memorable: {en: "The original LLaMA (24 Feb 2023) was meant only for approved researchers. Within about a week its weights were on a 4chan torrent and Meta was filing DMCA takedowns on GitHub. With Llama 2, Meta released openly what had leaked.",
               uk: "Первісна LLaMA (24 лютого 2023 р.) призначалася лише перевіреним дослідникам. Приблизно за тиждень її ваги опинилися в торенті на 4chan, а Meta розсилала вимоги DMCA на GitHub. З Llama 2 Meta відкрито випустила те, що раніше витекло."},
   numbers: [
     {label: {en: "Parameters", uk: "Параметри"}, value: "7B / 13B / 70B", note: {en: "dense", uk: "щільні (dense)"}, est: false},
     {label: {en: "Training data", uk: "Дані для навчання"}, value: "2.0T tokens", note: {en: "context 4K", uk: "контекст 4K"}, est: false},
     {label: {en: "Compute", uk: "Обчислення"}, value: "3.31M A100 GPU-hours", note: {en: "all sizes; 1.72M for 70B", uk: "усі розміри; 1,72 млн для 70B"}, est: false},
     {label: {en: "Llama downloads", uk: "Завантажень Llama"}, value: "~350M", note: {en: "all Llama models to date, by Aug 2024 (Meta)", uk: "усі моделі Llama за весь час, станом на серпень 2024 р. (Meta)"}, est: false}
   ],
   arch: "ARCH-rlhf", significance: 4, confidence: "high",
   caveat: {en: "Open weights (custom licence), not open source: the OSI says the Llama 2 licence is not open source. Meditron's performance claims are its authors' own.",
            uk: "Відкриті ваги (власна ліцензія), а не відкритий код: OSI вважає, що ліцензія Llama 2 не є open source. Заяви про результати Meditron належать її авторам."},
   sources: ["S-R5-03", "S-R5-04", "S-R5-05", "S-R5-02", "S-R5-30", "S-R5-26"]},

  {id: "M-2023-eo-bletchley", date: "2023-10-30", precision: "day", t: 2023.827, era: "E10",
   title: {en: "US Executive Order 14110 and the Bletchley Declaration", uk: "Указ президента США 14110 і Блетчлійська декларація"},
   who: {en: "US President Joe Biden; UK government (AI Safety Summit, Bletchley Park); 28 countries plus the EU", uk: "Президент США Джо Байден; уряд Великої Британії (саміт з безпеки ШІ, Блетчлі-Парк); 28 країн і ЄС"},
   kind: "policy",
   what: {en: "The US order told federal agencies to act on AI safety and security and, using the Defense Production Act, required developers to report on models trained with more than 10^26 operations. Two days later, 28 countries (including the US and China) and the EU signed a declaration saying frontier AI could cause serious, even catastrophic, harm and that they would cooperate on safety research.",
          uk: "Указ зобов'язав федеральні відомства США діяти в питаннях безпеки ШІ і, спираючись на Закон про оборонне виробництво, вимагав від розробників звітувати про моделі, навчені з понад 10^26 операцій. Через два дні 28 країн (зокрема США й Китай) та ЄС підписали декларацію про те, що передовий ШІ може завдати серйозної, навіть катастрофічної шкоди, і що вони співпрацюватимуть у дослідженнях безпеки."},
   why: {en: "It was one of the first government policies to use a training-compute threshold. And the US and China signed the same statement recognising frontier-AI risk as a shared problem.",
         uk: "Це була одна з перших державних політик із порогом за обчислювальним бюджетом навчання. А США й Китай підписали одну й ту саму заяву, визнавши ризик передового ШІ спільною проблемою."},
   example: {en: "Under the order, a company had to report to the federal government if it trained a model with more than 10^26 integer or floating-point operations, or 10^23 for models trained mainly on biological sequence data. Reporting also applied to anyone owning a co-located computing cluster capable of 10^20 operations per second.",
             uk: "За указом компанія мала звітувати федеральному уряду, якщо навчала модель із понад 10^26 цілочисельних операцій або операцій з рухомою комою, або 10^23 для моделей, навчених переважно на біологічних послідовностях. Звітувати мусив і кожен власник розміщеного на одному майданчику обчислювального кластера потужністю 10^20 операцій за секунду."},
   memorable: {en: "The order did not survive the change of administration: President Trump revoked EO 14110 on his first day in office, 20 Jan 2025 (EO 14148).",
               uk: "Указ не пережив зміни адміністрації: президент Трамп скасував EO 14110 у перший день на посаді, 20 січня 2025 р. (EO 14148)."},
   numbers: [
     {label: {en: "Compute reporting threshold", uk: "Поріг звітування за обчисленнями"}, value: "10^26 operations", note: {en: "10^23 for models trained mainly on biological sequence data", uk: "10^23 для моделей, навчених переважно на біологічних послідовностях"}, est: false},
     {label: {en: "Cluster threshold", uk: "Поріг для кластерів"}, value: "10^20 ops/s", note: {en: "with >100 Gbit/s networking", uk: "з мережею понад 100 Гбіт/с"}, est: false},
     {label: {en: "Bletchley signatories", uk: "Підписанти Блетчлійської декларації"}, value: "28 countries + EU", note: {en: "at signing; the UK government page now lists 30 including the EU", uk: "на момент підписання; сторінка уряду Британії тепер налічує 30, включно з ЄС"}, est: false}
   ],
   arch: null, significance: 4, confidence: "high",
   caveat: null,
   sources: ["S-R7a-39", "S-R7a-40", "S-R7a-41"]},

  {id: "M-2023-openai-board", date: "2023-11-17", precision: "day", t: 2023.877, era: "E10",
   title: {en: "OpenAI's board fires and rehires Altman", uk: "Рада OpenAI звільняє і повертає Альтмана"},
   who: {en: "OpenAI's nonprofit board; Sam Altman; Greg Brockman; Microsoft (Satya Nadella)", uk: "Рада некомерційної OpenAI; Сем Альтман; Грег Брокман; Microsoft (Сатья Наделла)"},
   kind: "event",
   what: {en: "The board of OpenAI's nonprofit removed CEO Sam Altman, saying he had been \"not consistently candid\" with it. Microsoft then offered jobs to Altman and Brockman, and nearly all staff threatened to follow. Within five days the board agreed to reinstate Altman under a new initial board (Bret Taylor as chair, Larry Summers, Adam D'Angelo).",
          uk: "Рада некомерційної OpenAI усунула гендиректора Сема Альтмана, заявивши, що він був «не завжди відвертим» із нею. Microsoft одразу запропонувала роботу Альтману й Брокману, і майже весь персонал пригрозив піти за ними. За п'ять днів рада погодилася повернути Альтмана під новою початковою радою (Брет Тейлор як голова, Ларрі Саммерс, Адам Д'Анджело)."},
   why: {en: "It tested whether a nonprofit board focused on safety could actually control the leading commercial AI lab. Employees, investors and Microsoft proved to have more leverage. The governance of frontier labs became a mainstream policy question.",
         uk: "Це стало перевіркою, чи може некомерційна рада, зосереджена на безпеці, справді контролювати провідну комерційну лабораторію ШІ. Більше важелів виявилося у працівників, інвесторів і Microsoft. Урядування передових лабораторій стало питанням великої політики."},
   example: {en: "About 745 of OpenAI's roughly 770 employees signed an open letter to the board, including board member and chief scientist Ilya Sutskever, who publicly apologised for his part in the firing.",
             uk: "Близько 745 із приблизно 770 працівників OpenAI підписали відкритий лист до ради, зокрема й член ради та головний науковець Ілля Суцкевер, який публічно вибачився за свою роль у звільненні."},
   memorable: {en: "OpenAI had three CEOs in three days: Altman, then interim CEO Mira Murati (17 Nov), then former Twitch CEO Emmett Shear (19 Nov). Then Altman returned.",
               uk: "За три дні в OpenAI змінилося троє гендиректорів: Альтман, потім тимчасова гендиректорка Міра Мураті (17 листопада), потім колишній гендиректор Twitch Еммет Шір (19 листопада). А тоді Альтман повернувся."},
   numbers: [
     {label: {en: "Duration", uk: "Тривалість"}, value: "~5 days", note: {en: "17–21 Nov 2023", uk: "17–21 листопада 2023 р."}, est: false},
     {label: {en: "Staff letter", uk: "Лист працівників"}, value: "~745 of ~770", note: {en: "counts rose over the weekend; reports vary", uk: "кількість зростала протягом вікенду; дані різняться"}, est: true}
   ],
   arch: null, significance: 4, confidence: "high",
   caveat: {en: "Exact signature counts vary between reports.", uk: "Точна кількість підписів різниться між повідомленнями."},
   sources: ["S-R7a-42", "S-R7a-43"]},

  {id: "M-2023-gemini", date: "2023-12-06", precision: "day", t: 2023.929, era: "E10",
   title: {en: "Gemini 1.0: Google's natively multimodal answer", uk: "Gemini 1.0: від природи мультимодальна відповідь Google"},
   who: {en: "Google DeepMind / Google (Sundar Pichai, Demis Hassabis)", uk: "Google DeepMind / Google (Сундар Пічаї, Деміс Гассабіс)"},
   kind: "model",
   what: {en: "A family of three sizes (Ultra, Pro and Nano) built to be natively multimodal: pre-trained from the start on text, images, audio and video, instead of bolting a vision model onto a text model afterwards.",
          uk: "Сімейство трьох розмірів (Ultra, Pro і Nano), від самого початку мультимодальне: моделі попередньо навчали одразу на тексті, зображеннях, аудіо та відео, а не додавали модель зору до текстової згодом."},
   why: {en: "It was the first credible frontier rival to GPT-4 from Google, the company where the Transformer was invented. Within two months it replaced the Bard brand.",
         uk: "Це був перший переконливий передовий суперник GPT-4 від Google — компанії, де винайшли трансформер. За два місяці він замінив бренд Bard."},
   example: {en: "Gemini Nano ran on the Pixel 8 Pro phone itself, for features such as Summarize. On 8 Feb 2024 Bard became Gemini, with Gemini Advanced (Ultra 1.0) at $19.99 a month.",
             uk: "Gemini Nano працювала безпосередньо на телефоні Pixel 8 Pro, наприклад для функції Summarize. 8 лютого 2024 р. Bard став Gemini, а Gemini Advanced (Ultra 1.0) коштував $19,99 на місяць."},
   memorable: {en: "Google's viral \"Hands-on with Gemini\" video was not real-time: Google said it had prompted the model with still frames from the footage plus text, then edited the result (TechCrunch, 7 Dec 2023).",
               uk: "Вірусне відео Google «Hands-on with Gemini» не було записом у реальному часі: Google визнала, що подавала моделі стоп-кадри з відео разом із текстом, а потім змонтувала результат (TechCrunch, 7 грудня 2023 р.)."},
   numbers: [
     {label: {en: "MMLU, Gemini Ultra", uk: "MMLU, Gemini Ultra"}, value: "90.0% (CoT@32)", note: {en: "83.7% in standard 5-shot vs GPT-4's reported 86.4%", uk: "83,7% у стандартному 5-shot проти заявлених 86,4% у GPT-4"}, est: false},
     {label: {en: "Benchmarks won by Ultra", uk: "Бенчмарків, виграних Ultra"}, value: "30 of 32", note: {en: "vs the previous state of the art (Google)", uk: "проти попереднього найкращого результату (за даними Google)"}, est: false},
     {label: {en: "Parameters", uk: "Параметри"}, value: "undisclosed", note: null, est: false}
   ],
   arch: "ARCH-multimodal", significance: 4, confidence: "high",
   caveat: {en: "Google-reported numbers. The headline MMLU comparison mixes prompting methods: Ultra beat the human-expert estimate only with 32-sample chain of thought; in standard 5-shot it scored 83.7%, below GPT-4's 86.4%.",
            uk: "Цифри за даними Google. Гучне порівняння MMLU змішує методи промптингу: Ultra перевершила оцінку рівня експертів лише з ланцюжком міркувань на 32 вибірках; у стандартному 5-shot вона набрала 83,7%, менше за 86,4% у GPT-4."},
   sources: ["S-R7a-44", "S-R7a-45", "S-R7a-46", "S-R7a-47"]},

  // ---------------------------------------------------------------- E11 · Multimodal, long context, open weights (2024)
  {id: "M-2024-gemini15-long-context", date: "2024-02-15", precision: "day", t: 2024.123, era: "E11",
   title: {en: "Gemini 1.5 and the million-token context", uk: "Gemini 1.5 і контекст на мільйон токенів"},
   who: {en: "Google DeepMind", uk: "Google DeepMind"},
   kind: "model",
   what: {en: "A mixture-of-experts model that could read up to 1 million tokens in one prompt: about 1 hour of video, 11 hours of audio, 30,000+ lines of code or 700,000+ words. Google tested up to 10 million tokens in research.",
          uk: "Модель на суміші експертів, що читала до 1 млн токенів в одному промпті: близько 1 години відео, 11 годин аудіо, понад 30 тис. рядків коду або понад 700 тис. слів. У дослідженнях Google випробувала до 10 млн токенів."},
   why: {en: "It capped a race in which the usable context of leading models grew about 125-fold in 11 months. Putting a whole codebase, book or video into the prompt became a real alternative to retrieval pipelines.",
         uk: "Це стало вершиною перегонів, у яких корисне контекстне вікно провідних моделей зросло приблизно у 125 разів за 11 місяців. Покласти в промпт цілу кодову базу, книжку чи відео стало реальною альтернативою конвеєрам пошуку (retrieval)."},
   example: {en: "Google showed the model answering questions across the 402-page transcripts of the Apollo 11 Moon mission in a single prompt.",
             uk: "Google показала, як модель відповідає на запитання за 402-сторінковими стенограмами місячної місії «Аполлон-11» в одному промпті."},
   memorable: {en: "In May 2023 Anthropic showed off Claude's 100K window by changing one line of The Great Gatsby (72K tokens) so that the narrator worked on machine-learning tooling at Anthropic. Claude Instant found the change in 22 seconds.",
               uk: "У травні 2023 р. Anthropic продемонструвала 100-тисячне вікно Claude, змінивши один рядок у «Великому Ґетсбі» (72 тис. токенів) так, щоб оповідач працював над інструментами машинного навчання в Anthropic. Claude Instant знайшов зміну за 22 секунди."},
   numbers: [
     {label: {en: "Context", uk: "Контекст"}, value: "1M tokens", note: {en: "limited preview; 128K standard; 10M in research", uk: "обмежене прев'ю; 128K стандартно; 10 млн у дослідженнях"}, est: false},
     {label: {en: "Needle-in-a-haystack recall", uk: "Пошук «голки в копиці сіна»"}, value: ">99%", note: {en: "at 1M tokens", uk: "на 1 млн токенів"}, est: false},
     {label: {en: "Context race", uk: "Перегони контексту"}, value: "8K → 1M in 11 months", note: {en: "GPT-4 8K (Mar 2023), Claude 100K (May), GPT-4 Turbo 128K and Claude 2.1 200K (Nov), Gemini 1.5 1M (Feb 2024)", uk: "GPT-4 8K (березень 2023), Claude 100K (травень), GPT-4 Turbo 128K і Claude 2.1 200K (листопад), Gemini 1.5 1M (лютий 2024)"}, est: false}
   ],
   arch: "ARCH-moe", significance: 4, confidence: "high",
   caveat: null,
   sources: ["S-R7a-52", "S-R7a-53", "S-R7a-54", "S-R7a-55", "S-R7a-18"]},

  {id: "M-2024-sora", date: "2024-02-15", precision: "day", t: 2024.123, era: "E11",
   title: {en: "Sora preview: minute-long video from text", uk: "Прев'ю Sora: хвилинне відео з тексту"},
   who: {en: "OpenAI", uk: "OpenAI"},
   kind: "model",
   what: {en: "A \"diffusion transformer\" that generates up to a minute of high-quality video from a text prompt. It works on \"spacetime patches\" of compressed video, the video equivalent of text tokens.",
          uk: "«Дифузійний трансформер», що генерує до хвилини якісного відео з текстового промпту. Він працює з «просторово-часовими фрагментами» стисненого відео — відеоаналогом текстових токенів."},
   why: {en: "Earlier video generators were typically trained on short clips (OpenAI cites 4-second, 256×256 examples). Sora jumped to coherent minute-long scenes, and its samples improved markedly from base to 4x to 32x training compute, showing that the Transformer scaling recipe also works for video. It brought deepfake and creative-industry worries into the mainstream.",
         uk: "Попередні генератори відео зазвичай навчали на коротких кліпах (OpenAI наводить приклади по 4 секунди при 256×256). Sora стрибнула до зв'язних хвилинних сцен, а її зразки помітно кращали від базового обчислювального бюджету до 4x і 32x — доказ, що рецепт масштабування трансформерів працює і для відео. Тривоги щодо дипфейків і творчих індустрій вийшли в мейнстрим."},
   example: {en: "Filmmaker Tyler Perry said he had put an $800 million expansion of his Atlanta studio on hold after seeing Sora (The Hollywood Reporter, Feb 2024).",
             uk: "Режисер Тайлер Перрі заявив, що після перегляду Sora призупинив розширення своєї студії в Атланті вартістю $800 млн (The Hollywood Reporter, лютий 2024 р.)."},
   memorable: {en: "OpenAI unveiled Sora on the same day Google announced Gemini 1.5. OpenAI's own report admitted that Sora could not reliably model basic physics such as glass shattering.",
               uk: "OpenAI показала Sora того ж дня, коли Google анонсувала Gemini 1.5. У власному звіті OpenAI визнала, що Sora не може надійно моделювати базову фізику, як-от розбиття скла."},
   numbers: [
     {label: {en: "Video length", uk: "Тривалість відео"}, value: "up to 60 s", note: null, est: false},
     {label: {en: "Scaling demo", uk: "Демонстрація масштабування"}, value: "base → 4x → 32x compute", note: {en: "params and compute undisclosed", uk: "параметри й обчислення не розкрито"}, est: false},
     {label: {en: "Public release", uk: "Публічний реліз"}, value: "9 Dec 2024", note: {en: "Feb 2024 access: red-teamers plus selected artists, designers and filmmakers", uk: "у лютому 2024 р. доступ мали лише red-team-тестувальники та вибрані митці, дизайнери й режисери"}, est: false}
   ],
   arch: null, significance: 4, confidence: "high",
   caveat: {en: "The Perry figure rests on a secondary source.", uk: "Цифра щодо Перрі спирається на вторинне джерело."},
   sources: ["S-R7a-56", "S-R7a-57", "S-R7a-58"]},

  {id: "M-2024-gpt4o", date: "2024-05-13", precision: "day", t: 2024.364, era: "E11",
   title: {en: "GPT-4o: one network for text, vision and real-time voice", uk: "GPT-4o: одна мережа для тексту, зору й голосу в реальному часі"},
   who: {en: "OpenAI", uk: "OpenAI"},
   kind: "model",
   what: {en: "An \"omni\" model trained end to end on text, images and audio. One neural network hears, sees and speaks, replacing the old chain of speech-to-text, language model and text-to-speech.",
          uk: "«Омні»-модель, навчена наскрізно на тексті, зображеннях і звуку. Одна нейронна мережа чує, бачить і говорить, замінюючи старий ланцюжок «розпізнавання мовлення → мовна модель → синтез мовлення»."},
   why: {en: "It made natural, interruptible voice conversation possible, with replies about as fast as human turn-taking, and it made a GPT-4-class model free to all ChatGPT users. It defined the natively multimodal design for assistants.",
         uk: "Вона уможливила природну голосову розмову, яку можна перебивати, з відповідями приблизно такої ж швидкості, як обмін репліками між людьми, і зробила модель класу GPT-4 безкоштовною для всіх користувачів ChatGPT. Вона визначила природно мультимодальний дизайн асистентів."},
   example: {en: "OpenAI's launch demos included live spoken translation between two people, and a session with Andy, a Be My Eyes user in London.",
             uk: "Серед демо на запуску — живий усний переклад між двома людьми та сеанс з Енді, користувачем Be My Eyes із Лондона."},
   memorable: {en: "A week after launch, on 20 May 2024, OpenAI paused its \"Sky\" voice amid comparisons with Scarlett Johansson's voice; the next day Johansson said she was shocked and angered by the resemblance. GPT-4o was retired from ChatGPT on 13 Feb 2026.",
               uk: "Через тиждень після запуску, 20 травня 2024 р., OpenAI призупинила голос «Sky» через порівняння з голосом Скарлетт Йоганссон; наступного дня Йоганссон заявила, що шокована й обурена схожістю. GPT-4o вивели з ChatGPT 13 лютого 2026 р."},
   numbers: [
     {label: {en: "Audio reply latency", uk: "Затримка голосової відповіді"}, value: "232–320 ms", note: {en: "minimum / average, vs 2.8 s (GPT-3.5) and 5.4 s (GPT-4) for the earlier voice chain", uk: "мінімум / середнє, проти 2,8 с (GPT-3.5) і 5,4 с (GPT-4) у попередньому голосовому ланцюжку"}, est: false},
     {label: {en: "Price at launch", uk: "Ціна на запуску"}, value: "$5 / $15 per 1M tokens", note: {en: "half of GPT-4 Turbo's $10 / $30; later cut to $2.50 / $10", uk: "удвічі дешевше за GPT-4 Turbo ($10 / $30); пізніше знижено до $2,50 / $10"}, est: false},
     {label: {en: "MMLU", uk: "MMLU"}, value: "88.7%", note: {en: "vs GPT-4 Turbo 86.5% (OpenAI chart)", uk: "проти 86,5% у GPT-4 Turbo (графік OpenAI)"}, est: false},
     {label: {en: "Speed", uk: "Швидкість"}, value: "2x GPT-4 Turbo", note: {en: "with 5x rate limits", uk: "із 5-кратними лімітами запитів"}, est: false}
   ],
   arch: "ARCH-multimodal", significance: 5, confidence: "high",
   caveat: null,
   sources: ["S-R7a-60", "S-R7a-61", "S-R7a-62", "S-R7a-63", "S-R7a-26"]},

  {id: "M-2024-claude35-sonnet", date: "2024-06-20", precision: "day", t: 2024.468, era: "E11",
   title: {en: "Claude 3.5 Sonnet and Artifacts", uk: "Claude 3.5 Sonnet і Artifacts"},
   who: {en: "Anthropic", uk: "Anthropic"},
   kind: "model",
   what: {en: "A mid-priced model that beat Anthropic's own larger Claude 3 Opus, and rival flagships, on key benchmarks, at twice Opus's speed for one fifth of the price. It launched with Artifacts, a panel in claude.ai that shows generated code, documents and small web apps next to the chat so users can refine them.",
          uk: "Модель середньої цінової категорії, що обійшла більшу Claude 3 Opus від самої Anthropic і флагмани конкурентів на ключових бенчмарках, працюючи вдвічі швидше за Opus за п'яту частину ціни. Разом із нею з'явилися Artifacts — панель у claude.ai, де згенерований код, документи й маленькі вебзастосунки показуються поруч із чатом, щоб користувач міг їх доопрацьовувати."},
   why: {en: "Coding became the headline use. On Anthropic's internal agentic coding test (fix a bug or add a feature in an open-source codebase), it solved 64% of problems against 38% for Opus. This began Claude's lead in coding agents, and Artifacts turned the chat window into a workspace.",
         uk: "Головним застосуванням стало програмування. На внутрішньому агентному тесті Anthropic (виправити помилку чи додати функцію у відкритій кодовій базі) модель розв'язала 64% задач проти 38% в Opus. Так почалося лідерство Claude в агентах для програмування, а Artifacts перетворили вікно чату на робочий простір."},
   example: {en: "A user could ask for a website, chart or small game and see it rendered and editable in the Artifacts window next to the conversation.",
             uk: "Користувач міг попросити вебсайт, графік чи маленьку гру — і побачити результат у вікні Artifacts поруч із розмовою, готовий до редагування."},
   memorable: {en: "The middle tier (\"Sonnet\") overtook the company's top tier (\"Opus\") only 3.5 months after Opus launched.",
               uk: "Середній рівень («Sonnet») обійшов найвищий рівень компанії («Opus») лише через 3,5 місяця після запуску Opus."},
   numbers: [
     {label: {en: "Price", uk: "Ціна"}, value: "$3 / $15 per 1M tokens", note: {en: "vs Claude 3 Opus $15 / $75; context 200K", uk: "проти $15 / $75 у Claude 3 Opus; контекст 200K"}, est: false},
     {label: {en: "GPQA (0-shot CoT)", uk: "GPQA (0-shot CoT)"}, value: "59.4%", note: {en: "HumanEval 92.0% (Anthropic chart)", uk: "HumanEval 92,0% (графік Anthropic)"}, est: false},
     {label: {en: "Internal agentic coding eval", uk: "Внутрішній агентний тест програмування"}, value: "64%", note: {en: "vs 38% for Claude 3 Opus", uk: "проти 38% у Claude 3 Opus"}, est: false}
   ],
   arch: null, significance: 4, confidence: "high",
   caveat: null,
   sources: ["S-R7a-64", "S-R7a-67"]},

  {id: "M-2024-llama31-405b", date: "2024-07-23", precision: "day", t: 2024.559, era: "E11",
   title: {en: "Llama 3.1 405B: frontier-class open weights", uk: "Llama 3.1 405B: відкриті ваги передового класу"},
   who: {en: "Meta (Llama Team; Mark Zuckerberg's letter \"Open Source AI Is the Path Forward\")", uk: "Meta (команда Llama; лист Марка Цукерберга «Open Source AI Is the Path Forward»)"},
   kind: "model",
   what: {en: "Meta released the weights of a 405-billion-parameter dense Transformer trained on about 15.6 trillion tokens with a 128K context window. In Meta's own evaluations it scored close to GPT-4o and Claude 3.5 Sonnet.",
          uk: "Meta виклала ваги щільного трансформера на 405 млрд параметрів, навченого приблизно на 15,6 трлн токенів, із контекстним вікном 128K. За власними оцінками Meta, модель була близька до GPT-4o і Claude 3.5 Sonnet."},
   why: {en: "Meta called it the first frontier-level open model: its own benchmarks put it within a few points of GPT-4o and Claude 3.5 Sonnet rather than a generation behind. It cut the open–closed gap to months and let companies and governments run a GPT-4-class model on their own hardware. Its licence also newly allowed Llama outputs to be used to improve other models.",
         uk: "Meta назвала її першою відкритою моделлю передового рівня: за власними бенчмарками вона відставала від GPT-4o і Claude 3.5 Sonnet лише на кілька пунктів, а не на покоління. Розрив між відкритими й закритими моделями скоротився до місяців, а компанії та уряди змогли запускати модель класу GPT-4 на власному обладнанні. Ліцензія вперше дозволила використовувати результати Llama для покращення інших моделей."},
   example: {en: "Meta's own assistant, Meta AI, was built on Llama 3 and offered inside Facebook, Instagram, WhatsApp and Messenger. Meta reported 300M+ total downloads of all Llama models by July 2024.",
             uk: "Власний асистент Meta AI збудували на Llama 3 і вбудували у Facebook, Instagram, WhatsApp і Messenger. За даними Meta, усі моделі Llama до липня 2024 р. завантажили понад 300 млн разів."},
   memorable: {en: "At 3.8×10^25 FLOPs, Llama 3.1 405B was above the EU AI Act's 10^25 FLOP threshold for presumed \"systemic-risk\" models, but below the US executive order's 10^26 reporting threshold.",
               uk: "З бюджетом 3,8×10^25 FLOP Llama 3.1 405B перевищувала поріг 10^25 FLOP, за яким Акт ЄС про ШІ презюмує «системний ризик», але не досягала порогу 10^26 для звітування за указом США."},
   numbers: [
     {label: {en: "Parameters", uk: "Параметри"}, value: "405B", note: {en: "dense, not MoE; context 128K", uk: "щільна, не MoE; контекст 128K"}, est: false},
     {label: {en: "Training compute", uk: "Обчислювальний бюджет навчання"}, value: "3.8×10^25 FLOP", note: {en: "up to 16K H100 GPUs", uk: "до 16 тис. GPU H100"}, est: false},
     {label: {en: "Training data", uk: "Дані для навчання"}, value: "15.6T tokens", note: null, est: false},
     {label: {en: "MMLU (5-shot)", uk: "MMLU (5-shot)"}, value: "87.3%", note: {en: "vs GPT-4o 89.1 and Claude 3.5 Sonnet 89.9 (Meta's table)", uk: "проти 89,1 у GPT-4o і 89,9 у Claude 3.5 Sonnet (таблиця Meta)"}, est: false}
   ],
   arch: "ARCH-rlhf", significance: 5, confidence: "high",
   caveat: {en: "Comparisons are Meta's own evaluations. Open weights (custom licence), not open source.", uk: "Порівняння — власні оцінки Meta. Відкриті ваги (власна ліцензія), а не відкритий код."},
   sources: ["S-R7a-65", "S-R7a-66", "S-R7a-67", "S-R7a-68"]},

  {id: "M-2024-eu-ai-act", date: "2024-08-01", precision: "day", t: 2024.584, era: "E11",
   title: {en: "EU AI Act enters into force (amended 2026)", uk: "Акт ЄС про ШІ набуває чинності (зі змінами 2026 р.)"},
   who: {en: "European Union (Parliament, Council, Commission)", uk: "Європейський Союз (Парламент, Рада, Комісія)"},
   kind: "policy",
   what: {en: "The first comprehensive AI law. It bans some uses (for example government social scoring) and places strict duties on high-risk systems (recruitment or medical software, for example). Chatbots must disclose that users are talking to a machine, and providers of general-purpose AI models have their own obligations.",
          uk: "Перший всеохопний закон про ШІ. Він забороняє деякі застосування (наприклад, державний соціальний рейтинг) і накладає суворі обов'язки на системи високого ризику (скажімо, ПЗ для найму чи медицини). Чат-боти мають повідомляти, що користувач спілкується з машиною, а провайдери моделей ШІ загального призначення мають власні зобов'язання."},
   why: {en: "It created the first binding, cross-sector legal framework for AI in a major market, including rules for foundation models. A training-compute threshold of 10^25 FLOPs triggers a presumption of \"systemic risk\" and extra duties.",
         uk: "Він створив перші обов'язкові міжгалузеві правові рамки для ШІ на великому ринку, зокрема правила для базових моделей. Поріг обчислювального бюджету навчання 10^25 FLOP вмикає презумпцію «системного ризику» й додаткові обов'язки."},
   example: {en: "The bans applied from 2 Feb 2025 and the obligations for general-purpose AI models from 2 Aug 2025. The 2026 \"Digital Omnibus on AI\" (Regulation (EU) 2026/1744, in force 27 Jul 2026) moved the high-risk obligations for Annex III uses to 2 Dec 2027 and for AI in regulated products (Annex I) to 2 Aug 2028, and added a ban on AI that generates non-consensual intimate imagery or child sexual abuse material (from 2 Dec 2026).",
             uk: "Заборони діють з 2 лютого 2025 р., а обов'язки для моделей загального призначення — з 2 серпня 2025 р. «Цифровий омнібус щодо ШІ» 2026 року (Регламент (ЄС) 2026/1744, чинний з 27 липня 2026 р.) переніс обов'язки для систем високого ризику з Додатка III на 2 грудня 2027 р., а для ШІ в регульованих продуктах (Додаток I) — на 2 серпня 2028 р., і додав заборону ШІ, що генерує інтимні зображення без згоди або матеріали сексуального насильства над дітьми (з 2 грудня 2026 р.)."},
   memorable: {en: "The EU's threshold (10^25 FLOPs) is ten times lower than the 10^26 used by the US order of Oct 2023. A model the size of Llama 3.1 405B falls under the EU rule but was below the US reporting line.",
               uk: "Поріг ЄС (10^25 FLOP) удесятеро нижчий за 10^26 з указу США від жовтня 2023 р. Модель розміру Llama 3.1 405B підпадає під правило ЄС, але не досягала американської лінії звітування."},
   numbers: [
     {label: {en: "Systemic-risk threshold", uk: "Поріг системного ризику"}, value: "10^25 FLOP", note: {en: "Art. 51", uk: "ст. 51"}, est: false},
     {label: {en: "Maximum fine", uk: "Максимальний штраф"}, value: "€35M or 7%", note: {en: "of worldwide annual turnover, for prohibited practices (Art. 99); €15M or 3% for most other breaches", uk: "світового річного обороту, за заборонені практики (ст. 99); €15 млн або 3% за більшість інших порушень"}, est: false},
     {label: {en: "Published / in force", uk: "Опубліковано / набув чинності"}, value: "12 Jul / 1 Aug 2024", note: {en: "Regulation (EU) 2024/1689", uk: "Регламент (ЄС) 2024/1689"}, est: false},
     {label: {en: "Amended high-risk deadlines", uk: "Перенесені строки для високого ризику"}, value: "2 Dec 2027 / 2 Aug 2028", note: {en: "Annex III / Annex I (Digital Omnibus, 2026); GPAI enforcement 2 Aug 2026 unchanged", uk: "Додаток III / Додаток I (Цифровий омнібус, 2026); застосування правил для GPAI з 2 серпня 2026 р. без змін"}, est: false}
   ],
   arch: null, significance: 4, confidence: "high",
   caveat: null,
   sources: ["S-R7a-69", "S-R7a-70", "S-R7a-71", "S-R7a-72", "S-R7a-73", "S-AUD-01", "S-AUD-02"]}
);
// --- PART-2: E12 (Sep 2024 – Apr 2025), milestones 49–58. The 12 E13 milestones (59–70) live in milestones-d.js. ---
(window.AIH.milestones = window.AIH.milestones || []).push(
  // ---------------------------------------------------------------- E12 · Reasoning models (Sep 2024 – Apr 2025)
  {id: "M-2024-o1-preview", date: "2024-09-12", precision: "day", t: 2024.699, era: "E12",
   title: {en: "o1-preview: models that think before they answer", uk: "o1-preview: моделі, які думають, перш ніж відповісти"},
   who: {en: "OpenAI", uk: "OpenAI"},
   kind: "model",
   what: {en: "The first widely released \"reasoning model\": a language model trained with large-scale reinforcement learning to write a long, hidden chain of thought before it answers. o1-preview and o1-mini went into ChatGPT (Plus/Team) and to top-tier API users the same day the post \"Learning to Reason with LLMs\" was published; the full o1 followed on 5 Dec 2024 (ChatGPT) and 17 Dec (API).",
          uk: "Перша широко випущена «модель міркування»: мовна модель, яку за допомогою масштабного навчання з підкріпленням навчили писати довгий прихований ланцюжок міркувань, перш ніж відповісти. o1-preview і o1-mini з'явилися в ChatGPT (Plus/Team) та в API для користувачів найвищого рівня того ж дня, коли вийшов допис «Learning to Reason with LLMs»; повна o1 вийшла 5 грудня 2024 р. (ChatGPT) і 17 грудня (API)."},
   why: {en: "It opened a second scaling axis. OpenAI showed accuracy rising roughly with the logarithm of the compute spent \"thinking\" at answer time (test-time compute), not only with training compute. Within about six months every major lab had shipped a reasoning model.",
         uk: "Це відкрило другу вісь масштабування. OpenAI показала, що точність зростає приблизно як логарифм обчислень, витрачених на «роздуми» під час відповіді (test-time compute), а не лише разом з обчислювальним бюджетом навчання. Приблизно за пів року модель міркування випустила кожна велика лабораторія."},
   example: {en: "GitHub began testing o1-preview inside GitHub Copilot on release day, and a week later (19 Sep 2024) added o1-preview and o1-mini to Copilot Chat in VS Code and to the GitHub Models playground.",
             uk: "GitHub почав тестувати o1-preview у GitHub Copilot у день релізу, а через тиждень (19 вересня 2024 р.) додав o1-preview і o1-mini до Copilot Chat у VS Code та до майданчика GitHub Models."},
   memorable: {en: "Developers pay for thinking they never see. The raw chain of thought is hidden by design but billed as output tokens, and OpenAI forbids users from trying to extract it.",
               uk: "Розробники платять за роздуми, яких ніколи не бачать. Сирий ланцюжок міркувань прихований навмисно, але тарифікується як вихідні токени, а OpenAI забороняє користувачам намагатися його видобути."},
   numbers: [
     {label: {en: "Parameters", uk: "Параметри"}, value: "undisclosed", note: {en: "training details undisclosed beyond \"large-scale RL on chain of thought\"", uk: "деталі навчання не розкрито, окрім «масштабного RL на ланцюжку міркувань»"}, est: false},
     {label: {en: "AIME 2024, full o1", uk: "AIME 2024, повна o1"}, value: "74% / 83% / 93%", note: {en: "single sample / majority vote of 64 samples / re-ranking 1,000 samples; GPT-4o 12% (1.8 of 15 problems); OpenAI-reported", uk: "одна спроба / голосування 64 спроб / переранжування 1 000 спроб; GPT-4o — 12% (1,8 із 15 задач); за даними OpenAI"}, est: false},
     {label: {en: "GPQA Diamond (pass@1)", uk: "GPQA Diamond (pass@1)"}, value: "77.3%", note: {en: "o1 vs GPT-4o 50.6%; the first model to beat the PhD-expert baseline; Codeforces 89th percentile", uk: "o1 проти 50,6% у GPT-4o; перша модель, що обійшла базовий рівень експертів з PhD; Codeforces — 89-й процентиль"}, est: false},
     {label: {en: "Maximum output", uk: "Максимальний вихід"}, value: "32,768 / 65,536 tokens", note: {en: "o1-preview / o1-mini; hidden reasoning tokens are billed as output", uk: "o1-preview / o1-mini; приховані токени міркувань тарифікуються як вихідні"}, est: false}
   ],
   arch: "ARCH-reasoning", significance: 5, confidence: "high",
   caveat: {en: "Scores are OpenAI-reported, and the AIME figures are for the full o1 (Dec 2024), not the preview. Training details were never disclosed beyond \"large-scale RL on chain of thought\".",
            uk: "Результати — за даними OpenAI, а цифри AIME стосуються повної o1 (грудень 2024 р.), а не прев'ю. Деталі навчання так і не розкрили, окрім «масштабного RL на ланцюжку міркувань»."},
   sources: ["S-R7b-01", "S-R7b-02", "S-R7b-03", "S-R7b-04", "S-R3-63"]},

  {id: "M-2024-nobel-prizes", date: "2024-10-08", precision: "day", t: 2024.770, era: "E12",
   title: {en: "Two Nobel Prizes for AI in two days", uk: "Дві Нобелівські премії за ШІ за два дні"},
   who: {en: "John J. Hopfield, Geoffrey Hinton (Physics); David Baker, Demis Hassabis, John Jumper (Chemistry) — Royal Swedish Academy of Sciences",
         uk: "Джон Гопфілд, Джеффрі Гінтон (фізика); Девід Бейкер, Деміс Гассабіс, Джон Джампер (хімія) — Шведська королівська академія наук"},
   kind: "event",
   what: {en: "The Physics prize went to Hopfield and Hinton \"for foundational discoveries and inventions that enable machine learning with artificial neural networks\". The next day (9 Oct 2024), half of the Chemistry prize went to Hassabis and Jumper of Google DeepMind \"for protein structure prediction\" with AlphaFold2, and half to Baker \"for computational protein design\".",
          uk: "Премію з фізики присудили Гопфілду й Гінтону «за фундаментальні відкриття та винаходи, які уможливлюють машинне навчання за допомогою штучних нейронних мереж». Наступного дня (9 жовтня 2024 р.) половину премії з хімії отримали Гассабіс і Джампер з Google DeepMind «за передбачення структури білків» завдяки AlphaFold2, а другу половину — Бейкер «за комп'ютерний дизайн білків»."},
   why: {en: "Science's most prestigious award formally recognised neural networks as foundational science, and AI as a working instrument of discovery rather than only a consumer product.",
         uk: "Найпрестижніша наукова нагорода офіційно визнала нейронні мережі фундаментальною наукою, а ШІ — робочим інструментом відкриттів, а не лише споживчим продуктом."},
   example: {en: "According to the Nobel committee, AlphaFold2 has predicted the structure of virtually all of the roughly 200 million known proteins and has been used by more than two million people in 190 countries.",
             uk: "За даними Нобелівського комітету, AlphaFold2 передбачила структуру практично всіх із приблизно 200 млн відомих білків, і нею скористалися понад два мільйони людей зі 190 країн."},
   memorable: {en: "AlphaFold2 was presented in 2020; four years later its creators were Nobel laureates.",
               uk: "AlphaFold2 представили 2020 року; через чотири роки її творці стали нобелівськими лауреатами."},
   numbers: [
     {label: {en: "AlphaFold2 users", uk: "Користувачів AlphaFold2"}, value: "2M+", note: {en: "in 190 countries (Nobel committee, Oct 2024)", uk: "зі 190 країн (Нобелівський комітет, жовтень 2024 р.)"}, est: false},
     {label: {en: "Protein structures predicted", uk: "Передбачених структур білків"}, value: "~200M", note: {en: "virtually all known proteins", uk: "практично всі відомі білки"}, est: false}
   ],
   arch: null, significance: 4, confidence: "high",
   caveat: null,
   sources: ["S-R7b-05", "S-R7b-06"]},

  {id: "M-2024-computer-use", date: "2024-10-22", precision: "day", t: 2024.808, era: "E12",
   title: {en: "Claude \"computer use\": an AI that operates a desktop", uk: "Claude і «керування комп'ютером»: ШІ, який сам працює за комп'ютером"},
   who: {en: "Anthropic", uk: "Anthropic"},
   kind: "product",
   what: {en: "An API capability, released as a public beta on the Anthropic API, Amazon Bedrock and Google Vertex AI alongside an upgraded Claude 3.5 Sonnet, that lets Claude look at screenshots and drive a computer as a person does: moving the cursor, clicking buttons and typing text.",
          uk: "Можливість в API, випущена як публічна бета на Anthropic API, Amazon Bedrock і Google Vertex AI разом з оновленою Claude 3.5 Sonnet: Claude дивиться на знімки екрана й керує комп'ютером, як людина, — рухає курсор, натискає кнопки й набирає текст."},
   why: {en: "It was the first frontier model offered publicly with general control of graphical interfaces. Agents no longer needed a purpose-built API for every app: anything with a screen became reachable. OpenAI (Operator, Jan 2025) and Google followed.",
         uk: "Це була перша передова модель, публічно доступна із загальним керуванням графічними інтерфейсами. Агентам більше не був потрібен спеціальний API для кожного застосунку: досяжним стало все, що має екран. Слідом пішли OpenAI (Operator, січень 2025 р.) і Google."},
   example: {en: "Replit used it to build a tool that checks apps while they are being built for its Replit Agent. Asana, Canva, Cognition, DoorDash and The Browser Company also tested it at launch.",
             uk: "Replit використав її, щоб створити інструмент, який перевіряє застосунки для Replit Agent ще під час їх побудови. На старті її також тестували Asana, Canva, Cognition, DoorDash і The Browser Company."},
   memorable: {en: "By Anthropic's own account, while it was recording the launch demos Claude accidentally stopped a long screen recording, losing all the footage. In another run it wandered off mid-task to browse photos of Yellowstone National Park.",
               uk: "За словами самої Anthropic, під час запису демо до запуску Claude випадково зупинив тривалий запис екрана і втратив увесь відзнятий матеріал. В іншому прогоні він посеред завдання відволікся на перегляд фотографій Єллоустонського національного парку."},
   numbers: [
     {label: {en: "OSWorld (screenshot-only)", uk: "OSWorld (лише знімки екрана)"}, value: "14.9%", note: {en: "vs 7.8% for the next-best AI; 22.0% with more steps; human baseline 72.4%", uk: "проти 7,8% у наступного найкращого ШІ; 22,0% з більшою кількістю кроків; людський рівень — 72,4%"}, est: false},
     {label: {en: "OSWorld, later Claude models", uk: "OSWorld, пізніші моделі Claude"}, value: "61.4% → 86.0%", note: {en: "Claude Sonnet 4.5 (Sep 2025); Claude Fable 5 on OSWorld-Verified (Aug 2026), above the human baseline", uk: "Claude Sonnet 4.5 (вересень 2025 р.); Claude Fable 5 на OSWorld-Verified (серпень 2026 р.), вище людського рівня"}, est: false},
     {label: {en: "SWE-bench Verified, Claude 3.5 Sonnet", uk: "SWE-bench Verified, Claude 3.5 Sonnet"}, value: "33.4% → 49.0%", note: {en: "the upgraded Claude 3.5 Sonnet vs the June version (Anthropic-reported)", uk: "оновлена Claude 3.5 Sonnet проти червневої версії (за даними Anthropic)"}, est: false}
   ],
   arch: "ARCH-agents", significance: 4, confidence: "high",
   caveat: {en: "OSWorld numbers are developer-reported. At launch Anthropic itself called computer use \"at times cumbersome and error-prone\".",
            uk: "Результати OSWorld — за даними розробника. На старті сама Anthropic назвала керування комп'ютером «часом незграбним і схильним до помилок»."},
   sources: ["S-R7b-07", "S-R7b-08", "S-R7b-09", "S-R7b-10", "S-R7b-102", "S-R4a-25"]},

  {id: "M-2024-mcp", date: "2024-11-25", precision: "day", t: 2024.901, era: "E12",
   title: {en: "Model Context Protocol: a \"USB port\" for AI tools", uk: "Model Context Protocol: «USB-порт» для інструментів ШІ"},
   who: {en: "David Soria Parra, Justin Spahr-Summers — Anthropic", uk: "Девід Сорія Парра, Джастін Спар-Саммерс — Anthropic"},
   kind: "system",
   what: {en: "An open protocol, built on JSON-RPC 2.0 messages, that standardises how an AI application connects to outside tools and data. Each system (GitHub, Slack, a database) gets one \"MCP server\", which any compatible AI client can use. The specification, SDKs and reference servers were open-sourced on day one.",
          uk: "Відкритий протокол на повідомленнях JSON-RPC 2.0, який стандартизує, як застосунок на ШІ під'єднується до зовнішніх інструментів і даних. Кожна система (GitHub, Slack, база даних) отримує один «MCP-сервер», яким може користуватися будь-який сумісний ШІ-клієнт. Специфікацію, SDK та еталонні сервери відкрили з першого дня."},
   why: {en: "It replaced one-off, vendor-specific connectors with a shared standard. OpenAI adopted it in March 2025, and Google's complementary Agent2Agent (A2A) protocol, for agents talking to agents, launched on 9 Apr 2025 with 50+ partners. In December 2025 Anthropic donated MCP to the new Agentic AI Foundation under the Linux Foundation, which it co-founded with Block and OpenAI.",
         uk: "Він замінив одноразові конектори кожного постачальника спільним стандартом. OpenAI перейняла його в березні 2025 р., а 9 квітня 2025 р. Google запустила доповнювальний протокол Agent2Agent (A2A) для спілкування агентів між собою, з понад 50 партнерами. У грудні 2025 р. Anthropic передала MCP новій Agentic AI Foundation під егідою Linux Foundation, яку заснувала разом із Block та OpenAI."},
   example: {en: "At launch, Block and Apollo integrated MCP, and Zed, Replit, Codeium and Sourcegraph began building on it. By December 2025 ChatGPT, Cursor, Gemini, Microsoft Copilot and VS Code all supported it.",
             uk: "На старті MCP інтегрували Block і Apollo, а Zed, Replit, Codeium і Sourcegraph почали на ньому будувати. До грудня 2025 р. його підтримували ChatGPT, Cursor, Gemini, Microsoft Copilot і VS Code."},
   memorable: {en: "The design borrows from the Language Server Protocol, which lets one code editor support every programming language; MCP tries to do the same for AI tools. A 28 Jul 2026 revision made every request self-contained (\"stateless\").",
               uk: "Задум запозичено з Language Server Protocol, який дає одному редактору коду підтримувати всі мови програмування; MCP намагається зробити те саме для інструментів ШІ. Ревізія від 28 липня 2026 р. зробила кожен запит самодостатнім («без стану»)."},
   numbers: [
     {label: {en: "Active public MCP servers", uk: "Активних публічних MCP-серверів"}, value: "10,000+", note: {en: "Anthropic, Dec 2025", uk: "Anthropic, грудень 2025 р."}, est: false},
     {label: {en: "Monthly SDK downloads", uk: "Завантажень SDK на місяць"}, value: "97M+", note: {en: "Python + TypeScript (Anthropic, Dec 2025)", uk: "Python + TypeScript (Anthropic, грудень 2025 р.)"}, est: false}
   ],
   arch: "ARCH-agents", significance: 4, confidence: "high",
   caveat: {en: "Adoption counts are Anthropic-reported.", uk: "Показники впровадження — за даними Anthropic."},
   sources: ["S-R7b-11", "S-R7b-12", "S-R7b-13", "S-R7b-14", "S-R7b-15"]},

  {id: "M-2024-o3", date: "2024-12-20", precision: "day", t: 2024.970, era: "E12",
   title: {en: "o3 announced: big jumps on ARC-AGI and FrontierMath, at a price", uk: "Анонс o3: великі стрибки на ARC-AGI і FrontierMath — за свою ціну"},
   who: {en: "OpenAI; ARC Prize Foundation and Epoch AI (independent benchmark operators)", uk: "OpenAI; ARC Prize Foundation та Epoch AI (незалежні оператори бенчмарків)"},
   kind: "model",
   what: {en: "OpenAI previewed o3, the successor to o1 (it skipped the name \"o2\"), with benchmark results but no public release. Its results were far beyond earlier models on hard reasoning tests. o3-mini followed on 31 Jan 2025; o3 and o4-mini on 16 Apr 2025.",
          uk: "OpenAI показала o3, наступницю o1 (назву «o2» пропустили), з результатами бенчмарків, але без публічного релізу. На складних тестах на міркування її результати були далеко попереду попередніх моделей. o3-mini вийшла 31 січня 2025 р.; o3 та o4-mini — 16 квітня 2025 р."},
   why: {en: "It suggested test-time compute could crack benchmarks designed to resist memorisation. It also made cost per task a headline number: the best ARC-AGI-1 score needed about 172 times more compute than the \"efficient\" run.",
         uk: "Це натякало, що обчислення під час відповіді можуть зламати бенчмарки, створені стійкими до запам'ятовування. Водночас вартість однієї задачі стала головною цифрою: найкращий результат на ARC-AGI-1 вимагав приблизно у 172 рази більше обчислень, ніж «економний» прогін."},
   example: {en: "The ARC Prize Foundation verified o3's ARC-AGI-1 result on its semi-private test set and published the cost per task. It then made efficiency a required metric for its leaderboard.",
             uk: "ARC Prize Foundation перевірила результат o3 на напівзакритому тестовому наборі ARC-AGI-1 і опублікувала вартість однієї задачі. Після цього ефективність стала обов'язковою метрикою її таблиці лідерів."},
   memorable: {en: "The o3 released in April 2025 was a different, smaller model. ARC Prize measured it at 41–53% on ARC-AGI-1 (under 3% on ARC-AGI-2), and Epoch AI's own FrontierMath run scored about 10%. It also emerged that OpenAI had funded FrontierMath and could see most of its problems.",
               uk: "o3, випущена у квітні 2025 р., була іншою, меншою моделлю. ARC Prize виміряла їй 41–53% на ARC-AGI-1 (менш як 3% на ARC-AGI-2), а власний прогін FrontierMath від Epoch AI дав близько 10%. З'ясувалося також, що OpenAI фінансувала FrontierMath і мала доступ до більшості його задач."},
   numbers: [
     {label: {en: "ARC-AGI-1 (semi-private set)", uk: "ARC-AGI-1 (напівзакритий набір)"}, value: "75.7% / 87.5%", note: {en: "within the $10k public-leaderboard budget (6 samples) / at ~172× compute (1,024 samples); ARC Prize-verified", uk: "у межах бюджету $10 тис. публічної таблиці (6 спроб) / за ~172× обчислень (1 024 спроби); перевірено ARC Prize"}, est: false},
     {label: {en: "FrontierMath", uk: "FrontierMath"}, value: "~25%", note: {en: "OpenAI-reported, vs under 2% for the previous best", uk: "за даними OpenAI, проти менш як 2% у попереднього лідера"}, est: false},
     {label: {en: "SWE-bench Verified", uk: "SWE-bench Verified"}, value: "71.7%", note: {en: "Codeforces Elo 2727 (OpenAI-reported)", uk: "Codeforces Elo 2727 (за даними OpenAI)"}, est: false},
     {label: {en: "Cost per task, ARC-AGI-1", uk: "Вартість однієї задачі, ARC-AGI-1"}, value: "tens → thousands of $", note: {en: "ARC Prize estimates for the efficient and high-compute runs, revised several times as official prices appeared", uk: "оцінки ARC Prize для економного і високообчислювального прогонів, кілька разів переглянуті в міру появи офіційних цін"}, est: true}
   ],
   arch: "ARCH-reasoning", significance: 4, confidence: "high",
   caveat: {en: "The 87.5% was an unreleased preview at ~172× compute; the released o3 scored about 53% on ARC-AGI-1. FrontierMath 25% is medium confidence: run by OpenAI on a benchmark it funded, and Epoch's own run of the released o3 gave about 10%.",
            uk: "87,5% показало невипущене прев'ю за ~172× обчислень; випущена o3 набрала близько 53% на ARC-AGI-1. 25% на FrontierMath — середня впевненість: прогін робила OpenAI на бенчмарку, який сама фінансувала, а власний прогін Epoch для випущеної o3 дав близько 10%."},
   sources: ["S-R7b-16", "S-R7b-17", "S-R7b-18", "S-R7b-19", "S-R7b-20", "S-R7b-21"]},

  {id: "M-2024-deepseek-v3", date: "2024-12-26", precision: "day", t: 2024.986, era: "E12",
   title: {en: "DeepSeek-V3: near-frontier quality from a reported $5.6M final training run", uk: "DeepSeek-V3: майже передова якість за фінальний прогін навчання ціною близько $5,6 млн"},
   who: {en: "DeepSeek-AI (founder Liang Wenfeng) — DeepSeek, Hangzhou (spun out of the hedge fund High-Flyer)", uk: "DeepSeek-AI (засновник Лян Веньфен) — DeepSeek, Ханчжоу (виокремлена з хедж-фонду High-Flyer)"},
   kind: "model",
   what: {en: "A 671B-parameter mixture-of-experts model that uses only 37B parameters per token. It was trained on 14.8T tokens on 2,048 Nvidia H800s (an export-compliant chip) in under two months. It combined Multi-head Latent Attention, fine-grained experts, multi-token prediction and a new way of balancing work across experts.",
          uk: "Модель суміші експертів на 671 млрд параметрів, яка задіює лише 37 млрд параметрів на токен. Її навчили на 14,8 трлн токенів на 2 048 Nvidia H800 (чипі, дозволеному експортними правилами) менш ніж за два місяці. Вона поєднала Multi-head Latent Attention, дрібнозернистих експертів, передбачення кількох токенів і новий спосіб балансувати навантаження між експертами."},
   why: {en: "It matched leading closed models on many benchmarks with about 11× fewer GPU-hours than Llama 3.1 405B, and it became the base model for R1. It showed that export-restricted hardware plus careful engineering could reach the frontier, which undermined the assumption that only the biggest budgets could compete.",
         uk: "На багатьох бенчмарках вона зрівнялася з провідними закритими моделями, витративши приблизно в 11 разів менше GPU-годин, ніж Llama 3.1 405B, і стала базовою моделлю для R1. Вона показала, що обмежене експортом залізо плюс ретельна інженерія можуть вийти на передовий рівень, і підважила припущення, що змагатися можуть лише найбільші бюджети."},
   example: {en: "DeepSeek's chatbot app launched on 15 Jan 2025 running V3. By 27 Jan 2025 it had overtaken ChatGPT as the most-downloaded free app on the US iOS App Store, helped by R1's \"DeepThink\" mode.",
             uk: "Застосунок-чат-бот DeepSeek вийшов 15 січня 2025 р. на базі V3. До 27 січня 2025 р. він обійшов ChatGPT як найзавантажуваніший безкоштовний застосунок в американському iOS App Store, чому допоміг режим «DeepThink» на основі R1."},
   memorable: {en: "Both primary sources give GPU-hours. Llama 3.1 405B used 30.84M H100-hours; DeepSeek-V3 used 2.788M H800-hours, roughly one-eleventh.",
               uk: "Обидва первинні джерела наводять GPU-години. Llama 3.1 405B витратила 30,84 млн годин H100; DeepSeek-V3 — 2,788 млн годин H800, приблизно одну одинадцяту."},
   numbers: [
     {label: {en: "Parameters", uk: "Параметри"}, value: "671B / 37B active", note: {en: "mixture of experts; context 128K; 14.8T training tokens", uk: "суміш експертів; контекст 128K; 14,8 трлн токенів навчання"}, est: false},
     {label: {en: "Final training run", uk: "Фінальний прогін навчання"}, value: "2.788M H800 GPU-hours", note: {en: "est. ~3.3×10^24 FLOP (6 × 37B × 14.8T, a rule-of-thumb calculation)", uk: "оц. ~3,3×10^24 FLOP (6 × 37 млрд × 14,8 трлн, приблизний розрахунок)"}, est: true},
     {label: {en: "Cost", uk: "Вартість"}, value: "≈$5.6M", note: {en: "rental cost of the final training run only, at an assumed $2 per GPU-hour", uk: "лише орендна вартість фінального прогону навчання, за умовних $2 за GPU-годину"}, est: true},
     {label: {en: "API price", uk: "Ціна API"}, value: "$0.27 / $1.10 per 1M tokens", note: {en: "in (cache miss) / out, from 8 Feb 2025", uk: "вхід (без кешу) / вихід, з 8 лютого 2025 р."}, est: false}
   ],
   arch: "ARCH-moe", significance: 4, confidence: "high",
   caveat: {en: "The ≈$5.6M is a notional rental cost of the final training run only: DeepSeek itself says it excludes prior research and ablation experiments, and it also leaves out salaries and the purchase of the GPU fleet.",
            uk: "≈$5,6 млн — умовна орендна вартість лише фінального прогону навчання: DeepSeek сама зазначає, що сюди не входять попередні дослідження й абляційні експерименти, а також зарплати й купівля парку GPU."},
   sources: ["S-R5-58", "S-R5-59", "S-R5-60", "S-R5-10", "S-R5-64", "S-R5-74", "S-R5-77"]},

  {id: "M-2025-deepseek-r1", date: "2025-01-20", precision: "day", t: 2025.052, era: "E12",
   title: {en: "DeepSeek-R1: open-weights reasoning and a $590 billion shock", uk: "DeepSeek-R1: міркування з відкритими вагами і шок на $590 млрд"},
   who: {en: "DeepSeek (Hangzhou; funded by the hedge fund High-Flyer; CEO Liang Wenfeng)", uk: "DeepSeek (Ханчжоу; фінансується хедж-фондом High-Flyer; гендиректор Лян Веньфен)"},
   kind: "model",
   what: {en: "An open-weights reasoning model (MIT licence) that matched OpenAI's o1 on maths and coding. R1-Zero was trained from DeepSeek-V3-Base with large-scale reinforcement learning (GRPO), rewarded only for verifiably correct maths and code answers and with no human-written reasoning examples; R1 added a small \"cold-start\" supervised stage and multi-stage RL to make the reasoning readable. The full recipe was published, with six distilled 1.5B–70B versions.",
          uk: "Модель міркування з відкритими вагами (ліцензія MIT), яка зрівнялася з o1 від OpenAI у математиці й програмуванні. R1-Zero навчили з DeepSeek-V3-Base масштабним навчанням з підкріпленням (GRPO), винагороджуючи лише за перевірювано правильні відповіді з математики й коду і без жодних написаних людьми прикладів міркувань; R1 додала невеликий етап «холодного старту» з учителем і багатоетапне RL, щоб міркування стали читабельними. Повний рецепт опублікували разом із шістьма дистильованими версіями на 1,5–70 млрд параметрів."},
   why: {en: "It showed o1-style reasoning could be reproduced cheaply and openly. R1-Zero showed reasoning can emerge from RL alone, without human-written reasoning examples. It popularised the GRPO training algorithm, and within weeks OpenAI began showing more of its models' reasoning. The paper was peer-reviewed in Nature in September 2025.",
         uk: "Вона показала, що міркування в стилі o1 можна відтворити дешево й відкрито. R1-Zero довела, що міркування може виникнути із самого лише RL, без написаних людьми прикладів. Вона популяризувала алгоритм навчання GRPO, і за кілька тижнів OpenAI почала показувати більше міркувань своїх моделей. У вересні 2025 р. статтю опублікували в Nature після рецензування."},
   example: {en: "By 27 Jan 2025 the DeepSeek app was the most-downloaded free app on the US iOS App Store. That day Nvidia lost about $590 billion of market value (roughly 17%), at the time the largest one-day loss for any US company.",
             uk: "До 27 січня 2025 р. застосунок DeepSeek став найзавантажуванішим безкоштовним застосунком в американському iOS App Store. Того дня Nvidia втратила близько $590 млрд капіталізації (приблизно 17%) — на той час найбільшу одноденну втрату серед усіх американських компаній."},
   memorable: {en: "The paper reports an \"aha moment\": midway through training, R1-Zero spontaneously began re-checking its own work \"using an anthropomorphic tone\". The authors wrote that it was an aha moment for them too.",
               uk: "Стаття описує «момент осяяння»: посеред навчання R1-Zero спонтанно почала перевіряти власну роботу, «вживаючи антропоморфний тон». Автори написали, що це був момент осяяння і для них."},
   numbers: [
     {label: {en: "Parameters", uk: "Параметри"}, value: "671B / 37B active", note: {en: "mixture of experts, built on DeepSeek-V3; context 128K", uk: "суміш експертів на основі DeepSeek-V3; контекст 128K"}, est: false},
     {label: {en: "AIME 2024 (pass@1)", uk: "AIME 2024 (pass@1)"}, value: "79.8%", note: {en: "MATH-500 97.3%, Codeforces Elo 2,029; R1-Zero rose from 15.6% to 71.0% on AIME during RL (86.7% with majority voting)", uk: "MATH-500 — 97,3%, Codeforces Elo — 2 029; R1-Zero за час RL піднялася з 15,6% до 71,0% на AIME (86,7% з голосуванням більшістю)"}, est: false},
     {label: {en: "API price", uk: "Ціна API"}, value: "$0.55 / $2.19 per 1M tokens", note: {en: "in (cache miss) / out", uk: "вхід (без кешу) / вихід"}, est: false},
     {label: {en: "Nvidia, 27 Jan 2025", uk: "Nvidia, 27 січня 2025 р."}, value: "−$590B", note: {en: "about 17% of market value in one day; variously reported as $589–600B", uk: "близько 17% капіталізації за день; у різних джерелах $589–600 млрд"}, est: true}
   ],
   arch: "ARCH-reasoning", significance: 5, confidence: "high",
   caveat: {en: "\"DeepSeek built R1 for $6 million\" is a mix-up: ≈$5.6M was the rental cost of V3's final training run only. R1's own reasoning stage cost about $0.3M (Nature, 2025). The market-value loss is variously reported as $589–600 billion.",
            uk: "«DeepSeek створила R1 за $6 млн» — плутанина: ≈$5,6 млн — це орендна вартість лише фінального прогону навчання V3. Власний етап міркувань R1 коштував близько $0,3 млн (Nature, 2025). Втрату капіталізації в різних джерелах оцінюють у $589–600 млрд."},
   sources: ["S-R7b-22", "S-R7b-23", "S-R7b-24", "S-R7b-25", "S-R7b-26", "S-R7b-27"]},

  {id: "M-2025-stargate", date: "2025-01-21", precision: "day", t: 2025.055, era: "E12",
   title: {en: "Stargate: a $500 billion compute bet", uk: "Stargate: ставка на обчислення в $500 млрд"},
   who: {en: "OpenAI, SoftBank, Oracle, MGX; announced at the White House with US President Donald Trump", uk: "OpenAI, SoftBank, Oracle, MGX; оголошено в Білому домі разом із президентом США Дональдом Трампом"},
   kind: "system",
   what: {en: "A joint venture to build AI data centres in the US for OpenAI, with $100 billion committed \"immediately\" and up to $500 billion over four years.",
          uk: "Спільне підприємство для будівництва дата-центрів ШІ у США для OpenAI: $100 млрд, зобов'язаних «негайно», і до $500 млрд за чотири роки."},
   why: {en: "It marked the shift from buying GPUs to building gigawatt-scale \"AI factories\" with national political backing. Compute and energy became the central currency of frontier AI.",
         uk: "Це позначило перехід від купівлі GPU до будівництва «фабрик ШІ» гігаватного масштабу з політичною підтримкою держави. Обчислення та енергія стали головною валютою передового ШІ."},
   example: {en: "The flagship campus in Abilene, Texas (developed by Crusoe and leased to Oracle) was where GPT-6 Astra was pretrained on more than 100,000 GPUs in 2026. By 23 Sep 2025 OpenAI had announced five more US sites, bringing planned capacity to nearly 7 GW.",
             uk: "Флагманський кампус в Абіліні, Техас (збудований Crusoe і зданий в оренду Oracle), — саме там 2026 року на понад 100 000 GPU проходило попереднє навчання GPT-6 Astra. До 23 вересня 2025 р. OpenAI оголосила ще п'ять майданчиків у США, довівши заплановану потужність майже до 7 ГВт."},
   memorable: {en: "Elon Musk claimed on launch day that the backers lacked the money. In August 2025 Bloomberg reported that funding for the full $500 billion had not yet been raised, yet a month later OpenAI said it was on track to secure the whole 10 GW ahead of schedule.",
               uk: "У день оголошення Ілон Маск заявив, що в інвесторів немає таких грошей. У серпні 2025 р. Bloomberg повідомив, що фінансування на повні $500 млрд ще не зібрано, однак за місяць OpenAI сказала, що йде з випередженням графіка до всіх 10 ГВт."},
   numbers: [
     {label: {en: "Announced investment", uk: "Оголошені інвестиції"}, value: "$100B → $500B", note: {en: "initial commitment; up to $500B by 2029 (plans, not money spent)", uk: "початкове зобов'язання; до $500 млрд до 2029 р. (плани, а не витрачені гроші)"}, est: false},
     {label: {en: "Target capacity", uk: "Цільова потужність"}, value: "10 GW", note: {en: "~7 GW planned and over $400B of planned investment by Sep 2025", uk: "~7 ГВт заплановано і понад $400 млрд запланованих інвестицій станом на вересень 2025 р."}, est: false}
   ],
   arch: null, significance: 4, confidence: "medium",
   caveat: {en: "Headline figures are announcements and plans, not money spent; delivered capacity in 2026 is far smaller than announced capacity.",
            uk: "Головні цифри — це оголошення і плани, а не витрачені гроші; введена в дію потужність у 2026 р. набагато менша за оголошену."},
   sources: ["S-R7b-28", "S-R7b-29", "S-R7b-90"]},

  {id: "M-2025-claude-code", date: "2025-02-24", precision: "day", t: 2025.148, era: "E12",
   title: {en: "Claude Code and the coding-agent boom", uk: "Claude Code і бум агентів для програмування"},
   who: {en: "Anthropic; OpenAI (Codex, May 2025)", uk: "Anthropic; OpenAI (Codex, травень 2025 р.)"},
   kind: "product",
   what: {en: "Claude 3.7 Sonnet was the first \"hybrid\" reasoning model: one model that can answer instantly or think step by step, with a visible thinking budget the user sets. Claude Code, launched the same day as a limited research preview, is a command-line agent that works inside a developer's own codebase: it searches and reads code, edits files, runs tests and commits to GitHub. It became generally available on 22 May 2025 with Claude 4, a week after OpenAI's Codex cloud agent (16 May 2025).",
          uk: "Claude 3.7 Sonnet стала першою «гібридною» моделлю міркування: одна модель може відповідати миттєво або думати крок за кроком, із видимим бюджетом на роздуми, який задає користувач. Claude Code, запущений того ж дня як обмежене дослідницьке прев'ю, — це агент командного рядка, який працює всередині кодової бази розробника: шукає й читає код, редагує файли, запускає тести й робить коміти в GitHub. 22 травня 2025 р. він став загальнодоступним разом із Claude 4 — через тиждень після хмарного агента Codex від OpenAI (16 травня 2025 р.)."},
   why: {en: "The terminal coding agent became the breakout agent product of 2025, and handing whole engineering tasks to agents that work for minutes to hours became a mainstream way to build software. Software engineering was the first field where AI agents did economically large volumes of real work, and Claude Code became Anthropic's fastest-growing product and a key driver of its 2026 revenue surge. \"Vibe coding\", a term Andrej Karpathy coined on 2 Feb 2025, went mainstream.",
         uk: "Агент для програмування в терміналі став проривним агентним продуктом 2025 року, а передавати агентам цілі інженерні задачі, над якими вони працюють хвилинами й годинами, стало звичним способом створювати ПЗ. Розробка програмного забезпечення стала першою галуззю, де агенти ШІ виконували економічно значущі обсяги реальної роботи, а Claude Code — найшвидше зростаючим продуктом Anthropic і ключовим рушієм її стрибка виручки 2026 року. «Вайб-кодинг» — термін, який Андрій Карпатий запропонував 2 лютого 2025 р., — пішов у маси."},
   example: {en: "In Anthropic's early testing, Claude Code finished in a single pass tasks that would normally take 45+ minutes of manual work. In May 2025 Rakuten ran Claude Opus 4 on a demanding open-source refactor that worked independently for 7 hours. By February 2026 Claude Code alone had a revenue run-rate above $2.5 billion.",
             uk: "У ранніх тестах Anthropic Claude Code за один прохід завершував задачі, які зазвичай вимагали 45+ хвилин ручної роботи. У травні 2025 р. Rakuten запустила Claude Opus 4 на складному рефакторингу відкритого коду, і той працював самостійно 7 годин. До лютого 2026 р. річний темп виручки (run-rate) самого лише Claude Code перевищив $2,5 млрд."},
   memorable: {en: "In early 2026 an analysis cited by Anthropic estimated that Claude Code authored 4% of all public GitHub commits worldwide, double the share of a month earlier. The launch post also noted that Claude 3.7 Sonnet beat all previous Claude models in Anthropic's Pokémon gameplay tests.",
               uk: "На початку 2026 р. аналіз, на який посилалася Anthropic, оцінив, що Claude Code є автором 4% усіх публічних комітів на GitHub у світі — удвічі більше, ніж місяцем раніше. У дописі про запуск також зазначили, що Claude 3.7 Sonnet обійшла всі попередні моделі Claude в тестах Anthropic на гру в Pokémon."},
   numbers: [
     {label: {en: "SWE-bench Verified, Claude 3.7 Sonnet", uk: "SWE-bench Verified, Claude 3.7 Sonnet"}, value: "63.7%", note: {en: "on the 489 runnable tasks (≈62.3% of all 500); 70.3% with parallel test-time compute (Anthropic-reported)", uk: "на 489 задачах, що запускалися (≈62,3% від усіх 500); 70,3% з паралельними обчисленнями під час відповіді (за даними Anthropic)"}, est: false},
     {label: {en: "SWE-bench Verified, Claude Opus 4", uk: "SWE-bench Verified, Claude Opus 4"}, value: "72.5%", note: {en: "Sonnet 4 72.7%; 79.4% / 80.2% with parallel test-time compute (Anthropic, May 2025)", uk: "Sonnet 4 — 72,7%; 79,4% / 80,2% з паралельними обчисленнями під час відповіді (Anthropic, травень 2025 р.)"}, est: false},
     {label: {en: "Price, Claude 3.7 Sonnet", uk: "Ціна, Claude 3.7 Sonnet"}, value: "$3 / $15 per 1M tokens", note: {en: "in / out, thinking tokens included; thinking budget up to the 128K-token output limit", uk: "вхід / вихід, разом із токенами роздумів; бюджет на роздуми — до ліміту виходу 128K токенів"}, est: false},
     {label: {en: "Claude Code run-rate revenue", uk: "Річний темп виручки Claude Code (run-rate)"}, value: ">$0.5B → $1B → >$2.5B", note: {en: "Aug 2025 → Nov 2025 → Feb 2026 (Anthropic); weekly active users doubled between 1 Jan and 12 Feb 2026; Codex had 2M+ weekly users by Mar 2026 (press)", uk: "серпень 2025 р. → листопад 2025 р. → лютий 2026 р. (Anthropic); щотижневі активні користувачі подвоїлися з 1 січня до 12 лютого 2026 р.; Codex мав 2 млн+ щотижневих користувачів до березня 2026 р. (преса)"}, est: false}
   ],
   arch: "ARCH-agents", significance: 5, confidence: "high",
   caveat: {en: "Benchmarks and revenue are Anthropic-reported; run-rate is an annualised rate, not booked revenue. The 4% GitHub share is a third-party estimate, and the Codex user figure comes from secondary sources.",
            uk: "Бенчмарки й виручка — за даними Anthropic; run-rate — це річний темп, а не фактична виручка. Частка 4% комітів на GitHub — оцінка третьої сторони, а цифра користувачів Codex — із вторинних джерел."},
   sources: ["S-R7b-33", "S-R7b-34", "S-R7b-43", "S-R7b-39", "S-R7b-40", "S-R4a-61", "S-R4a-64"]},

  {id: "M-2025-metr-time-horizons", date: "2025-03-19", precision: "day", t: 2025.211, era: "E12",
   title: {en: "METR's \"time horizon\": a ruler for agents", uk: "«Часовий горизонт» METR: лінійка для агентів"},
   who: {en: "METR (Model Evaluation & Threat Research)", uk: "METR (Model Evaluation & Threat Research)"},
   kind: "benchmark",
   what: {en: "A metric that asks how long a task an AI agent can complete with 50% reliability, measured in how long the task takes skilled humans. It uses 170 software and research tasks (228 in the Time Horizon 1.1 update of 29 Jan 2026).",
          uk: "Метрика, яка запитує, наскільки довгу задачу агент ШІ може виконати з надійністю 50%, вимірюючи довжину задачі часом, який на неї витрачають кваліфіковані люди. Вона спирається на 170 задач з програмування й досліджень (228 в оновленні Time Horizon 1.1 від 29 січня 2026 р.)."},
   why: {en: "It turned \"agents are getting better\" into a single trend line. The 50% time horizon has doubled about every 7 months since 2019, and about every 4 months since 2023 (2026 update). It became the most-cited evidence in debates about AI timelines.",
         uk: "Вона перетворила «агенти стають кращими» на одну лінію тренду. 50-відсотковий часовий горизонт подвоювався приблизно кожні 7 місяців із 2019 року і приблизно кожні 4 місяці з 2023-го (оновлення 2026 р.). Вона стала найцитованішим доказом у суперечках про часові рамки розвитку ШІ."},
   example: {en: "AI labs' system cards and risk reports now cite METR's measurements. Claude Opus 4.5 (Nov 2025), for example, measured about 4 h 53 min at 50% on the v1.1 task suite.",
             uk: "Системні картки й звіти про ризики лабораторій ШІ тепер посилаються на вимірювання METR. Claude Opus 4.5 (листопад 2025 р.), наприклад, отримала близько 4 год 53 хв на рівні 50% на наборі задач v1.1."},
   memorable: {en: "METR warns that measurements above about 16 hours are unreliable with its current task suite, so the newest models are at the limit of METR's ruler. For GPT-5.6 Sol it got about 11 h if cheating attempts counted as failures and over 270 h if they counted as successes.",
               uk: "METR попереджає, що вимірювання понад приблизно 16 годин ненадійні з її нинішнім набором задач, тож найновіші моделі вже на межі лінійки METR. Для GPT-5.6 Sol вона отримала близько 11 год, якщо спроби шахраювати рахувати за провали, і понад 270 год, якщо за успіхи."},
   numbers: [
     {label: {en: "50% horizon, 2019–2023", uk: "50% горизонт, 2019–2023"}, value: "seconds → ~4 min", note: {en: "GPT-2 (2019) a few seconds; GPT-4 (Mar 2023) ~4 min", uk: "GPT-2 (2019) — кілька секунд; GPT-4 (березень 2023 р.) — ~4 хв"}, est: false},
     {label: {en: "50% horizon, 2025", uk: "50% горизонт, 2025"}, value: "~1 h → ~3 h 23 min", note: {en: "Claude 3.7 Sonnet (Feb 2025) → GPT-5 (Aug 2025)", uk: "Claude 3.7 Sonnet (лютий 2025 р.) → GPT-5 (серпень 2025 р.)"}, est: false},
     {label: {en: "50% horizon, 2026", uk: "50% горизонт, 2026"}, value: "~12 h → ~17 h", note: {en: "Claude Opus 4.6 (Feb 2026; 95% CI ~5–60 h) → Claude Mythos Preview (Apr 2026; 95% CI ~8.5–55 h), at the limit of METR's ruler; 80% horizons are 4–10× shorter (Mythos Preview ~3.1 h)", uk: "Claude Opus 4.6 (лютий 2026 р.; 95% ДІ ~5–60 год) → Claude Mythos Preview (квітень 2026 р.; 95% ДІ ~8,5–55 год), на межі лінійки METR; 80-відсоткові горизонти в 4–10 разів коротші (Mythos Preview — ~3,1 год)"}, est: false},
     {label: {en: "Doubling time", uk: "Час подвоєння"}, value: "~188 → ~129 days", note: {en: "all-time → since 2023 (Time Horizon 1.1)", uk: "за весь час → з 2023 року (Time Horizon 1.1)"}, est: false}
   ],
   arch: "ARCH-agents", significance: 4, confidence: "high",
   caveat: {en: "Confidence intervals for the newest models are very wide, and horizons above ~16 h are at the limit of METR's ruler. No published horizon exists for GPT-6 Astra or Claude Opus 5.5.",
            uk: "Довірчі інтервали для найновіших моделей дуже широкі, а горизонти понад ~16 год — на межі лінійки METR. Для GPT-6 Astra і Claude Opus 5.5 опублікованого горизонту немає."},
   sources: ["S-R7b-35", "S-R7b-36", "S-R7b-95", "S-AUD-10"]}
);
